from itertools import product

def product_cardinality(values: tuple[bool, ...]) -> int:
    return int(all(values))

def witnesses(n: int) -> list[tuple[bool, ...]]:
    return [v for v in product((False, True), repeat=n)
            if product_cardinality(v) == n]

for n in range(7):
    print(n, witnesses(n))

def predicates_are_constant(size: int) -> bool:
    """The conclusion applies whenever the fixed-point condition can hold."""
    if size < 0:
        raise ValueError("size must be nonnegative")
    fixed_point_exists = size == 1
    all_boolean_predicates_constant = size <= 1
    return (not fixed_point_exists) or all_boolean_predicates_constant

for n in range(5):
    print(n, predicates_are_constant(n))

from math import prod

def matches_domain(fibers: tuple[int, ...]) -> bool:
    if any(k < 0 for k in fibers):
        raise ValueError("fiber sizes must be nonnegative")
    return prod(fibers) == len(fibers)

examples = [(1,), (2, 2, 1, 1), (2, 1), (3, 1, 1)]
for fibers in examples:
    print(fibers, prod(fibers), matches_domain(fibers))

